const items = $input.all();
const j = (items[0] && items[0].json) || {};
const meta = j.meta || {};
const errors = meta.errors || {};
const keys = Object.keys(errors);
if (keys.length > 0) {
  throw new Error('automation feed meta.errors: ' + JSON.stringify(errors));
}
return $input.all();

const items = $input.all();
const top = (items[0] && items[0].json) || {};
const data = top.data || (top.body && top.body.data) || {};
const meta = top.meta || (top.body && top.body.meta) || {};

const ev = Array.isArray(data.event) ? data.event : [];
const mk = (data.marketing && Array.isArray(data.marketing.events)) ? data.marketing.events : [];
const vip = (data.marketing && Array.isArray(data.marketing.vip)) ? data.marketing.vip : [];

// Menggabungkan EVENT dan MARKETING jadi satu array
const combinedEvents = [...ev, ...mk];

const dayNames = ['Minggu', 'Senin', 'Selasa', 'Rabu', 'Kamis', 'Jumat', 'Sabtu'];
const months = ['Jan', 'Feb', 'Mar', 'Apr', 'Mei', 'Jun', 'Jul', 'Agu', 'Sep', 'Okt', 'Nov', 'Des'];

function rupiah(n) {
  n = Number(n) || 0;
  return 'Rp. ' + n.toLocaleString('id-ID');
}

function tglIndo(iso) {
  const p = String(iso || '').split('-');
  if (p.length !== 3 || !p[0]) return String(iso || '');
  const dt = new Date(Number(p[0]), Number(p[1]) - 1, Number(p[2]));
  if (isNaN(dt.getTime())) return String(iso || '');
  return dayNames[dt.getDay()] + ', ' + Number(p[2]) + ' ' + months[Number(p[1]) - 1] + ' ' + p[0];
}

function jamMulai(s) {
  s = String(s || '');
  const m = s.match(/(\d{2}):(\d{2})/);
  return m ? m[0] : (s || '-');
}

const tgl = tglIndo(meta.date);
const total = combinedEvents.length + vip.length;

// JIKA TIDAK ADA EVENT
if (total === 0) {
  const linesEmpty = [];
  linesEmpty.push('Halo, Semangat Pagi Team! ☀️✨');
  linesEmpty.push('📅 *' + tgl + '*');
  linesEmpty.push('');
  linesEmpty.push('☕ Hari ini jadwal kita *FREE EVENT* alias nihil agenda!');
  linesEmpty.push('Yuk manfaatkan hari ini buat fokus pelayanan reguler, beberes area, atau sekadar nafas sejenak.');
  linesEmpty.push('');
  linesEmpty.push('Tetap semangat dan jaga kesehatan ya semuanya! 💪🔥');
  return [{ json: { text: linesEmpty.join('\n') } }];
}

// JIKA ADA EVENT
const lines = [];
lines.push('Halo, Selamat Pagi Team! 🖐️✨');
lines.push('Berikut rekap kegiatan & event untuk hari ini ya:');
lines.push('');
lines.push('📋 *INFO EVENT - ' + tgl + '*');
lines.push('📊 Total: ' + combinedEvents.length + ' Event/Marketing | ' + vip.length + ' VIP');
lines.push('----------------------------------');

if (combinedEvents.length) {
  lines.push('');
  lines.push('🎉 *DAFTAR EVENT:*');
  combinedEvents.forEach((r, i) => {
    const nm = '*' + String(r.nama || '-').toUpperCase() + '*';
    const jm = jamMulai(r.mulai || r.time || '--:--');
    const vn = String(r.venue || '-');
    const px = (r.pax !== undefined && r.pax !== null) ? r.pax + ' pax' : '';
    const st = String(r.status || '');
    const hari = (r.totalHari && r.totalHari > 1) ? ' (hari ' + r.hari + '/' + r.totalHari + ')' : '';

    let details = [nm];
    if (jm !== '--:--' && jm !== '-') details.push('⏰ ' + jm);
    if (vn !== '-') details.push('📍 ' + vn);
    if (px) details.push('👥 ' + px);
    if (st) details.push('📌 ' + st);

    lines.push((i + 1) + '. ' + details.join(' | ') + hari);
  });
}

if (vip.length) {
  lines.push('');
  lines.push('⭐ *VIP:*');
  vip.forEach((r, i) => {
    const nm = '*' + String(r.nama || '-').toUpperCase() + '*';
    const pt = String(r.perusahaan || '-');
    const jm = String(r.jam || '-');
    const px = (r.pax === undefined || r.pax === null) ? '-' : r.pax;
    const mj = Array.isArray(r.meja) ? r.meja.join(', ') : String(r.meja || '-');
    const nom = Number(r.nominal) || 0;
    const dp = nom > 0 ? rupiah(nom) : '❌ Belum DP';
    lines.push((i + 1) + '. ' + nm + ' | 🏢 ' + pt + ' | ⏰ ' + jm + ' | 👥 ' + px + ' pax | 🪑 Meja ' + mj + ' | 💳 ' + dp);
  });
}

lines.push('');
lines.push('----------------------------------');
lines.push('Tetap kompak, berikan pelayanan terbaik, dan semangat bertugas hari ini team! 💪🔥');

return [{ json: { text: lines.join('\n') } }];
